  const brick = { x: 80, y: 100, w: 40, h: 20 };
  // Ball top is 118, brick bottom is 120. Overlap = 2.
  const hit = resolveBrickCollision(ball, brick);
  assert.equal(hit, true);
  assert.equal(ball.vy, 100);
  assert.equal(ball.y, 120 + 7);
});

test('resolveBrickCollision: left hit flips vx and pushes left', () => {
  const ball = { x: 75, y: 110, r: 7, vx: 100, vy: 0 };
  const brick = { x: 80, y: 100, w: 40, h: 20 };
  // Ball right is 82, brick left is 80. Overlap = 2.
  const hit = resolveBrickCollision(ball, brick);
  assert.equal(hit, true);
  assert.equal(ball.vx, -100);
  assert.equal(ball.x, 80 - 7);
});

test('resolveBrickCollision: right hit flips vx and pushes right', () => {
  const ball = { x: 125, y: 110, r: 7, vx: -100, vy: 0 };
  const brick = { x: 80, y: 100, w: 40, h: 20 };
  // Ball left is 118, brick right is 120. Overlap = 2.
  const hit = resolveBrickCollision(ball, brick);
  assert.equal(hit, true);
  assert.equal(ball.vx, 100);
  assert.equal(ball.x, 120 + 7);
});

test('resolveBrickCollision: corner hit flips both', () => {
  const ball = { x: 75, y: 95, r: 7, vx: 100, vy: 100 };
  const brick = { x: 80, y: 100, w: 40, h: 20 };
  // Ball right: 82, Ball bottom: 102.
  // Penetrations: X=2, Y=2.
  const hit = resolveBrickCollision(ball, brick);
  assert.equal(hit, true);
  assert.equal(ball.vx, -100);
  assert.equal(ball.vy, -100);
});

test('step: tunnelling prevention (ball jumps over brick)', () => {
  const state = createState(1);
  // Ball is above the brick and moving very fast
  state.ball = { x: 100, y: 50, r: 7, vx: 0, vy: 2000 };
  // Brick is at y=60, h=20.
